insert into pulse_meeting_kinds (id, label, short_label, kind, cadence, day, time_of_day, dept_ids, blurb, ord) values
  ('hiring', 'Hiring', 'Hiring', 'hiring', 'weekly', 'monday', null, array['hiring']::text[], 'No decisions section. Hiring decisions are headcount-and-capital tradeoffs that get made where the money is, not here. A hiring decision raised on Monday carries to whichever charter owns the budget.', 1),
  ('india_charter', 'India & Perf India Charter', 'India & Perf India Charter', 'india_charter', 'weekly', 'tuesday', null, array['india_sales','perf_marketing']::text[], 'Spend and the pipeline it feeds, read in one room. Perf India''s CPL and the India pipeline sourced from paid are the same argument seen from two ends - splitting them across two meetings is what makes that argument impossible to have.', 2),
  ('us_charter', 'US & Perf US Charter', 'US & Perf US Charter', 'us_charter', 'weekly', 'wednesday', null, array['us_sales','perf_marketing']::text[], 'Same shape as Tuesday, in dollars.', 3),
  ('sloosh', 'Sloosh Product & Marketing', 'Sloosh Product & Marketing', 'sloosh', 'weekly', 'thursday', null, array['sloosh']::text[], 'Funnel, shipping and social. Weekly product numbers are noisy - a 4-week trailing view may read truer here than a week-on-week delta.', 4)
